/**
 * 工具栏图标。
 * 全部统一为 48×48 视图、4 单位线宽、currentColor 单色（跟随思源主题），
 * 不引入图标字体或外部资源，避免插件包变大、也避免思源主题变量缺失。
 * 图形取自用户提供的图标稿；序号与选择两个原稿为 1024 视图的实心图，
 * 这里按同样造型重画成线性描边，使线条粗细与其余图标一致。
 */

import type {ArrowHead, ArrowKind, ArrowStyleKey, ArrowType, ToolType} from "../types";
import {ARROW_PREVIEW, arrowPreview} from "./arrowGeometry";
import {cornerPreviewRadius} from "./cornerRadius";

/**
 * 统一外壳：线性图标的默认笔触；填充型元素在 body 里单独覆盖。
 * 带 annot-icon 类，index.css 里会用插件作用域的选择器把尺寸、笔触再固定一次，
 * 避免思源其它样式（或后续主题）改写图标外观，保证「界面里 = 预览图」。
 */
const wrap = (body: string, size = 20): string =>
    `<svg class="annot-icon" viewBox="0 0 48 48" width="${size}" height="${size}" fill="none" ` +
    `stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" ` +
    `aria-hidden="true">${body}</svg>`;

/** 填充型图标元素：继承 currentColor，不描边 */
const filled = (d: string): string => `<path d="${d}" fill="currentColor" stroke="none"/>`;

