/** 把 1024 视图图形等比缩放进 48 视图 */
const from1024 = (d: string): string =>
    `<path d="${d}" fill="currentColor" stroke="none" transform="scale(0.046875)"/>`;

/**
 * 用户定稿的镜像图标（1024 视图、实心 + 一侧镂空）：
 * 一半实心、一半描边轮廓，比原来「虚线 + 两个空心三角」更像"翻过来"。
 * 镂空那一半的边带在原稿约 50 单位，缩到 20px 显示后约 1px；
 * 为了不让它比旁边 4 单位线宽的图标显得虚，描一节 12 单位的补光描边
 * （48 视图下约 0.56 单位，几乎不改变外轮廓，只把细边压实）。
 */
const FLIP_H_1024 = "M928 896H546.304V128zM97.92 896h381.44V128L97.92 896z m334.08-49.92H170.24l261.76-518.4v518.4z";
