const mirrorIcon = (d: string): string =>
    // 内联 style 而不是属性：index.css 里有一条「[fill="currentColor"] → stroke:none」的
    // 兜底规则（防止空心图标被填实），属性会被它覆盖，内联样式的优先级更高。
    // 描边宽度 18（1024 空间）≈ 48 视图 0.84 单位：把镂空那一半约 1px 的细边压实一点，
    // 又不至于把两半中间的分缝糊掉（分缝仍有约 1px）。
    `<path d="${d}" fill="currentColor" stroke="currentColor" stroke-linejoin="round" ` +
    `style="stroke:currentColor;stroke-width:18" transform="scale(0.046875)"/>`;

