/**
 * 空心原稿外壳：视图与线宽按原稿比例写死。
 * 注意线宽必须写在每个 <path> 自己身上——样式表里 `.annot-icon-button > svg.annot-icon`
 * 有 stroke-width: 4，写在 svg 上会被它压掉（1024 视图会细到看不见）。
 */
const strokeSourceIcon = (body: string, viewBox: string, strokeWidth: number): string =>
    `<svg class="annot-icon" viewBox="${viewBox}" width="20" height="20" fill="none" ` +
    `stroke="currentColor" stroke-width="${strokeWidth}" stroke-linecap="round" ` +
    `stroke-linejoin="round" aria-hidden="true">${body}</svg>`;

