/**
 * 画布悬浮条里的「箭头样式」图案。
 * 与画布上的真实绘制共用 arrowGeometry.ts 的同一套几何（含 ShareX 的头宽比例），
 * 视图固定 48×20、描边 1.6，图案永远不会和实际画出来的形状分叉。
 */
export function arrowStyleIcon(kind: ArrowKind | ArrowStyleKey): string {
    const p = arrowPreview(kind);
    const parts: string[] = [];
    // 尖尾的杆是实心楔形，要填色；其余样式的杆只是一根线
    if (p.shaft) parts.push(`<path d="${p.shaft}" fill="${p.shaftFilled ? "currentColor" : "none"}"/>`);
    for (const head of p.heads) {
        parts.push(`<path d="${head.d}" fill="${head.fill ? "currentColor" : "none"}"/>`);
    }
    for (const bar of p.bars) {
        parts.push(`<line x1="${bar.x1}" y1="${bar.y1}" x2="${bar.x2}" y2="${bar.y2}"/>`);
    }
    return `<svg class="annot-arrow-style-icon" viewBox="0 0 ${ARROW_PREVIEW.width} ${ARROW_PREVIEW.height}" ` +
        `width="${ARROW_PREVIEW.width}" height="${ARROW_PREVIEW.height}" fill="none" stroke="currentColor" ` +
        `stroke-width="${ARROW_PREVIEW.lineWidth}" stroke-linecap="round" stroke-linejoin="round" ` +
        `aria-hidden="true">${parts.join("")}</svg>`;
}

/**
 * 矩形圆角档位的图案：只画左上角那一段折角（与 ShareX 的 CornerRadiusPreviewGeometry
 * 同一套「竖线 → 圆弧 → 横线」画法），半径按档位等比映射，0 档就是干净的直角。
 */
export function cornerRadiusIcon(radius: number): string {
    const r = cornerPreviewRadius(radius);
    const d = r <= 0.01
        ? "M3 17 L3 3 L17 3"
        : `M3 17 L3 ${3 + r} A ${r} ${r} 0 0 1 ${3 + r} 3 L17 3`;
    // 每个 path 必须自己写 fill="none"：思源的 util/_reset.scss 有一条 svg { fill: currentColor }，
    // 它是 CSS 声明，优先级高于写在 <svg> 上的 fill="none" 属性，只靠外层会被整块填实。
    return `<svg class="annot-corner-icon" viewBox="0 0 20 20" width="20" height="20" fill="none" ` +
        `stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" ` +
        `aria-hidden="true"><path fill="none" d="${d}"/></svg>`;
}

/**
 * 下拉按钮右侧的折角箭头（展开时 CSS 旋转 180°）。
 * 同样每个 path 自带 fill="none"，否则会被思源的全局填充规则染成实心三角。
 */
export const CHEVRON_DOWN_ICON =
    `<svg class="annot-chevron" viewBox="0 0 48 48" width="10" height="10" fill="none" ` +
    `stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" ` +
    `aria-hidden="true"><path fill="none" d="M12 19 L24 31 L36 19"/></svg>`;

/**
 * 箭头类型 / 端点样式的小图标：**手绘一套**，不走几何生成。
 * 几何版在 16px 高的小格子里头会糊成一团、楔形也看不出来，
 * 这里按参考图的比例直接把「箭头端的一小段」画出来，形状一眼可辨。
 * viewBox 40×24，头占右边三分之二，杆只留一小截。
 */
const arrowGlyph = (body: string): string =>
    `<svg class="annot-arrow-style-icon" viewBox="0 0 40 24" width="32" height="19" fill="none" ` +
    `stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" ` +
    `aria-hidden="true">${body}</svg>`;

